<script>
function sw(el,id){
  document.querySelectorAll('.titem').forEach(function(t){t.classList.remove('on');});
  document.querySelectorAll('.tp').forEach(function(p){p.classList.remove('on');});
  el.classList.add('on');
  document.getElementById(id).classList.add('on');
}
</script>
